import type { Types } from '@cornerstonejs/core';

export type ViewerBridgeViewMode = 'fourUp' | 'mpr' | 'primary3D';

export type ViewerToOhifMessage =
  | { type: 'SET_3D_PRESET'; preset: string }
  | { type: 'SET_3D_WW_WC'; windowWidth: number; windowCenter: number }
  | { type: 'OPEN_NATIVE_RENDERING_PANEL' }
  | { type: 'SET_VIEW_MODE'; viewMode: ViewerBridgeViewMode }
  | {
      type: 'SET_SCREW_PLANS';
      studyId: string;
      plans: Array<{
        _id: string;
        studyId: string;
        studyInstanceUID: string;
        name: string;
        frameOfReferenceUID: string;
        entryPoint: { x: number; y: number; z: number };
        targetPoint: { x: number; y: number; z: number };
        diameterMm: number;
        color: string;
        createdBy?: string;
      }>;
    }
  | {
      type: 'ACTIVATE_SCREW_PLAN';
      studyId: string;
      planId: string | null;
    }
  | {
      type: 'START_SCREW_PLAN_DRAW';
      studyId: string;
      planId?: string | null;
      plan?: {
        _id: string;
        studyId: string;
        studyInstanceUID: string;
        name: string;
        frameOfReferenceUID: string;
        entryPoint: { x: number; y: number; z: number };
        targetPoint: { x: number; y: number; z: number };
        diameterMm: number;
        color: string;
        createdBy?: string;
      };
      editOnly?: boolean;
    }
  | {
      type: 'NAVIGATE_TO_SCREW_PLAN';
      studyId: string;
      planId: string;
      entryPoint: { x: number; y: number; z: number };
      targetPoint: { x: number; y: number; z: number };
      frameOfReferenceUID: string;
    };

export type OhifToViewerMessage =
  | {
      type: 'ACTIVE_VIEWPORT_CHANGED';
      viewportId: string;
      viewportType?: string;
    }
  | {
      type: 'VIEWPORT_STATE_CHANGED';
      viewportId: string;
      viewportType?: string;
      displaySetInstanceUID?: string;
      preset?: string;
      windowWidth?: number;
      windowCenter?: number;
    }
  | {
      type: 'OHIF_COMMAND_FAILED';
      command: string;
      reason: string;
    }
  | {
      type: 'SCREW_PLANS_CHANGED';
      studyId: string;
      activePlanId: string | null;
      plans: Array<{
        _id: string;
        studyId: string;
        studyInstanceUID: string;
        name: string;
        frameOfReferenceUID: string;
        entryPoint: { x: number; y: number; z: number };
        targetPoint: { x: number; y: number; z: number };
        diameterMm: number;
        color: string;
        createdBy?: string;
      }>;
    };

export function postBridgeMessage(message: OhifToViewerMessage): void {
  if (typeof window === 'undefined' || window.parent === window) {
    return;
  }

  window.parent.postMessage(message, window.location.origin);
}

export function getViewportStatePayload(
  viewportId: string,
  viewport: Types.IViewport,
  displaySetInstanceUID?: string,
  preset?: string,
  windowWidth?: number,
  windowCenter?: number,
): OhifToViewerMessage {
  return {
    type: 'VIEWPORT_STATE_CHANGED',
    viewportId,
    viewportType: viewport?.type,
    displaySetInstanceUID,
    preset,
    windowWidth,
    windowCenter,
  };
}
